function Key() {}
const first = new Key();

Key.prototype.size = 1;
const second = new Key();

Key.prototype = { size: 2 };
const third = new Key();

console.log(first instanceof Key, second instanceof Key, third instanceof Key);
console.log(first.size, third.size);

Object.setPrototypeOf(first, Key.prototype);

console.log(first instanceof Key, second.constructor === Key, third.constructor === Key);
